{
  "passageId": "surface-tension-laplace",
  "items": [
    {
      "id": "R1",
      "type": "CAUSE",
      "otherName": "",
      "reason": "표면 장력이 실제로 방울을 표면적이 최소인 구형으로 만드는 작용을 하므로 인과 관계이다."
    },
    {
      "id": "R2",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "방울이 취하는 구형을 동일한 부피에서 표면적이 최소인 형태라는 성질로 더 자세히 설명한다."
    },
    {
      "id": "R3",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "방울에 작용하는 방향이라는 같은 기준에서 내부 압력의 팽창 작용과 나머지 압력의 수축 작용이 대조된다."
    },
    {
      "id": "R4",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "내부 압력이 팽창 방향으로 작용한다는 사실은 반대 방향의 압력과 균형을 이루면 크기가 유지된다는 설명을 뒷받침한다."
    },
    {
      "id": "R5",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "외부 압력과 표면 장력에 의한 압력의 수축 작용은 내부 압력과의 균형으로 크기가 유지되는 이유를 설명하는 근거이다."
    },
    {
      "id": "R6",
      "type": "DEFINITION",
      "otherName": "",
      "reason": "방울에 작용하는 압력들의 균형 관계를 라플라스 식이라는 수학적 관계로 표현한다."
    },
    {
      "id": "R7",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "압력 관계를 나타내는 라플라스 식의 내용을 압력 차이와 표면 장력의 정비례 관계로 구체화한다."
    },
    {
      "id": "R8",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "압력 관계를 나타내는 라플라스 식의 내용을 압력 차이와 반지름의 반비례 관계로 구체화한다."
    },
    {
      "id": "R9",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "공기가 고압에서 저압으로 이동한다는 일반 원리를 폐포 안팎의 공기 출입 현상에 적용한다."
    },
    {
      "id": "R10",
      "type": "PROBLEM_RESPONSE",
      "otherName": "",
      "reason": "폐포를 수축시키는 표면 장력에 대응하여 이를 낮추는 계면 활성제의 분비 기제가 제시된다."
    },
    {
      "id": "R11",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "표면 장력을 낮추는 계면 활성제라는 물질을 지질과 단백질이라는 구성 성분으로 더 자세히 설명한다."
    },
    {
      "id": "R12",
      "type": "CAUSE",
      "otherName": "",
      "reason": "계면 활성제에 의한 표면 장력 감소가 실제로 폐포의 확장을 쉽게 만든다."
    },
    {
      "id": "R13",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "앞에서 설명한 라플라스 식을 폐포의 압력과 표면 장력 관계라는 다른 현상에 적용한다."
    },
    {
      "id": "R14",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "액체 방울에서 설명한 표면 장력의 수축 작용을 폐포를 둘러싼 액체층에 적용한다."
    },
    {
      "id": "R15",
      "type": "CAUSE",
      "otherName": "",
      "reason": "두 기포 사이의 공기 이동이 두 기포를 더 큰 기포 하나로 합쳐지게 하는 실제 작용으로 제시된다."
    },
    {
      "id": "R16",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "라플라스 식을 크기가 다른 두 기포가 합쳐지는 현상을 이해하는 데 가져다 쓴다."
    },
    {
      "id": "R17",
      "type": "PROCESS",
      "otherName": "",
      "reason": "노즐에서 잉크가 분사된 다음 공기 중에서 방울이 되는 인쇄 과정의 순서를 설명한다."
    },
    {
      "id": "R18",
      "type": "PROCESS",
      "otherName": "",
      "reason": "공기 중에서 잉크 방울이 형성된 뒤 종이에 도달하는 단계적 순서를 나타낸다."
    },
    {
      "id": "R19",
      "type": "APPLICATION",
      "otherName": "",
      "reason": "일반적인 구형 방울의 압력 관계인 라플라스 식을 구형 잉크 방울에 적용하여 내외부 압력을 설명한다."
    },
    {
      "id": "R20",
      "type": "CONCESSION",
      "otherName": "",
      "reason": "잉크가 구형 방울로 형성되어 종이에 도달하더라도 그것만으로 제대로 된 인쇄가 보장되지는 않는다는 한계를 제시한다."
    },
    {
      "id": "R21",
      "type": "DEVELOPMENT",
      "otherName": "",
      "reason": "잉크 방울 형성의 한계를 지적한 뒤 안정적인 도착 정도와 이를 나타내는 지표로 논의를 옮긴다."
    },
    {
      "id": "R22",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "오네소르게 수의 네 결정 요인 중 점도의 뜻과 영향 방향을 구체적으로 설명한다."
    },
    {
      "id": "R23",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "오네소르게 수의 결정 요인 가운데 표면 장력·밀도·노즐 지름이 미치는 영향을 구체화한다."
    },
    {
      "id": "R24",
      "type": "CONTRAST",
      "otherName": "",
      "reason": "요인의 값이 증가할 때 오네소르게 수가 변하는 방향을 기준으로 점도와 나머지 세 요인의 영향을 대조한다."
    },
    {
      "id": "R25",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "네 요인과 오네소르게 수 사이의 관계를 근거로 요인을 조절하면 안정적인 인쇄가 가능하다는 결론을 도출한다."
    },
    {
      "id": "R26",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "오네소르게 수가 도착 안정성을 나타낸다는 사실이 그 결정 요인의 조절로 안정적인 인쇄가 가능하다는 판단을 뒷받침한다."
    },
    {
      "id": "R27",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "안정적인 인쇄를 위한 알맞은 조절을 오네소르게 수 0.1에서 1.0이라는 구체적인 범위로 설명한다."
    },
    {
      "id": "R28",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "점도가 클수록 오네소르게 수가 커진다는 관계를 안정 범위를 초과하는 구체적인 경우로 보여 준다."
    },
    {
      "id": "R29",
      "type": "CAUSE",
      "otherName": "",
      "reason": "큰 점도로 오네소르게 수가 안정 범위를 넘는 상황이 잉크가 노즐 밖으로 나오지 못하는 결과로 이어진다."
    },
    {
      "id": "R30",
      "type": "CAUSE",
      "otherName": "",
      "reason": "수많은 위성 잉크 방울의 발생이 실제로 원치 않는 오염을 일으킨다."
    },
    {
      "id": "R31",
      "type": "CONDITION",
      "otherName": "",
      "reason": "오네소르게 수가 안정 범위보다 큰 경우와 작은 경우에 따라 서로 다른 인쇄 문제가 발생하는 분기를 나타낸다."
    },
    {
      "id": "R32",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "안정적인 인쇄 범위의 의미를 점도가 커서 그 범위를 초과하면 잉크가 나오지 못하는 구체적인 사례로 설명한다."
    },
    {
      "id": "R33",
      "type": "ELABORATION",
      "otherName": "",
      "reason": "안정적인 인쇄 범위의 의미를 범위에 미달하면 위성 잉크 방울로 오염이 생기는 구체적인 경우로 설명한다."
    },
    {
      "id": "R34",
      "type": "PROCESS",
      "otherName": "",
      "reason": "네 요인으로 오네소르게 수를 결정한 뒤 그 산출값을 바탕으로 인쇄 안정성을 파악하는 단계적 절차이다."
    },
    {
      "id": "R35",
      "type": "GROUNDS",
      "otherName": "",
      "reason": "오네소르게 수의 범위별 인쇄 결과가 그 수로 안정적인 인쇄 가능 정도를 판단할 수 있다는 결론을 뒷받침한다."
    }
  ]
}

